-- Course: Master of Economics and Resource Policy (113828E)
UPDATE courses SET
    course_description = '<p>The Master of Economics and Resource Policy is a flexible two-year degree built around core economic principles. Study topics in global food and agricultural markets, principles of international trade and development and cost-benefit analysis. Advise on business strategy to optimise company performance within economic environments. Unravel the context behind major economic events such as recessions and inflation. Shape public policy locally and internationally.</p><p>Tailor your studies to suit your needs by selecting courses from a range of majors. Choose topics in economic analysis, global food and agribusiness, international trade and public economics and policy. Through your chosen courses, you’ll develop specialised knowledge in fields that align with your career goals, including opening a pathway to a PhD.</p><p>In your final year, conduct your own comprehensive applied research project and have the option to complete an internship. These features will ensure you graduate with relevant experience to kickstart or progress your career. Find employment across diverse sectors including public service, industry, consultancies, not-for-profits or private business.</p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or higher or equivalent from a recognised higher education institution; OR</li><li>A completed nested or related graduate certificate (AQF level 8) or higher or equivalent from a recognised higher education institution</li><li>This degree requires a Grade Point Average (GPA) equivalent to an Adelaide University 5.0 on a 7-point scale for entry</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications (link provided for comprehensive list of English language tests accepted)</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Possession of qualifications, in addition to the academic entry requirements, does not, in itself, guarantee a place at Adelaide University. Applications are considered on an individual basis and selection is competitive</li><li>Recognition of prior learning: Credit may be granted for formal, informal, and non-formal learning. Online Credit Assessor available. Visit Credit for previous study page for more information</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-economics-and-resource-policy/',
    updated_at = NOW()
WHERE cricos_course_code = '113828E';

-- Course: Graduate Certificate in Alcohol and Drug Studies (Available to non-student visa holder ONLY.)
UPDATE courses SET
    course_description = '<p>Build advanced knowledge around substance use and the ways in which addiction can be managed in our Graduate Certificate in Alcohol and Drug Studies. </p><p>What factors make a person more likely to develop a substance use issue? How does long-term drug or alcohol use affect brain pathways, and how is recovery possible? What roles do pharmacotherapies, harm reduction strategies, psychological therapies and education play in facilitating recovery? </p><p>In this part-time, completely online degree, you’ll explore evidence-based answers to these and many more questions. Learn how drugs affect the body and behaviour – including how drugs activate brain reward pathways, and the neurobiology that leads to tolerance, dependence and addiction. Examine factors that can predispose a person towards addiction, including biological, psychological and social circumstances. </p><p>You’ll emerge with a specialised skillset, ready to contribute to best practice approaches to managing substance abuse and addiction in your existing professional field. </p>',
    course_duration_per_week = 26,
    total_course_duration = '0.5 year(s) part-time only (no full-time option)',
    offshore_tuition_fee = 151500,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or equivalent from a recognised higher education institution.</td></tr><tr><td><strong>International Students</strong></td><td><ul><li>Program delivered online; open to international students studying online outside of Australia, or who do not require a student visa to undertake program in Australia.</li><li>Not available to international students wishing to study in Australia on a student visa.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within last two years prior to admission.</li><li>IELTS Overall 6.5, Reading 6, Listening 6, Speaking 6, Writing 6.</li><li>Where previous study/work experience was conducted in English, application must be accompanied by certified documentation certifying language of instruction/employment was English.</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>Admission criteria: eligible applicants must meet minimum entry requirement and demonstrate prerequisite and essential criteria.</li><li>If more eligible applicants than places, admission competitive with ranks based on entry criteria.</li><li>Recognition of prior learning: credit may be granted for formal, informal, and non-formal learning.</li></ul></td></tr></tbody></table>',
