-- Course: Master of Business Administration (0100793)
UPDATE courses SET
    course_description = '<p>Adelaide University’s Master of Business Administration is a 1.5-year degree, designed to provide experienced professionals with the skills and expertise to attain senior management and leadership positions across a range of industries and sectors. </p><p>Create new solutions, lead innovative teams and deliver exceptional results in the context of disruptive change and global uncertainty. Learn from real business case studies in the areas of sustainability, ethics, marketing and leadership. Bring your own experience to the table, with opportunities to address individual workplace situations.</p><p>According to the World Economic Forum’s Future of Jobs Report (<a href="https://www3.weforum.org/docs/WEF_Future_of_Jobs_2023.pdf" rel="noopener noreferrer" target="_blank">2023</a>), the most sought-after professionals will be those who can adapt to technological advancements and lead businesses to better environmental, social and governance outcomes. With our MBA, you’ll not only embrace innovation but also steer teams through any industry changes with success.</p>',
    course_duration_per_week = 78,
    total_course_duration = '1.5 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or equivalent from a recognised higher education institution</li><li>A minimum of 3 years of full-time (or equivalent) professional experience</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>IELTS Overall 7</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>To be eligible, an applicant must have achieved both minimum entry requirements and demonstrate they fulfil any prerequisite and essential criteria for admission</li><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Possession of qualifications, in addition to academic entry requirements, does not guarantee a place; applications considered individually and selection is competitive</li><li>Adelaide University recognises prior learning; credit may be granted for formal, informal, and non-formal learning</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-business-administration/',
    updated_at = NOW()
WHERE cricos_course_code = '0100793';

-- Course: Master of Business Analytics (107750F)
UPDATE courses SET
    course_description = '<p>This degree will build your knowledge in a range of business disciplines, while developing advanced skills in analytics. Explore fundamental business principles in economics, accounting and finance. Then, learn the higher-level concepts and tools essential for proficiency in business analytics, including managing big data, data visualisation, predictive analytics and text analytics. Tackle big questions in the field: What are future trends in analytics technology? How can we better integrate AI and machine learning? What are the ethical considerations of the sector? </p><p>The curriculum includes industry-related projects to sharpen your research and analytical skills. Graduate with sophisticated problem-solving and decision-making abilities, equipped for dynamic careers in business and management.</p>',
