-- Course: Master of Marketing (107748M)
UPDATE courses SET
    course_description = '<p>Our Master of Marketing is a two-year degree that will advance your marketing skills, preparing you to make strategic decisions and progress into leadership roles.</p><p>Be trained to develop effective marketing strategies for diverse audiences. Learn how to identify trends, analyse consumer behaviour, understand analytical data and communicate with impact. Develop the attitude of a global trailblazer with courses in leadership and entrepreneurship. Hone your skills with a marketing research project in your final year.</p><p>Depending on your level of experience, this degree could unlock senior marketing positions or an entirely new career. The principles you’ll learn in your master’s degree will be applicable to a variety of roles. Use your expert communication and analytical skills to contribute positively to any businesses and help drive growth.</p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 50500,
    onshore_tuition_fee = NULL,
