-- Course: Bachelor of Music Theatre (097917G)
UPDATE courses SET
    course_description = '<p>Become an industry-ready performer with a Bachelor of Music Theatre. Develop your skills in singing, dancing, acting and music. Receive individualised training, with countless opportunities to perform and hone your craft across all areas of music theatre. </p><p>Unlock exciting opportunities, where you’ll audition and be casted for music theatre performances. Take part in a major musical to a public audience and an industry showcase targeting agents, producers and directors. Learn professional etiquette and personal marketing. Graduate with everything you’ll need to launch yourself into the music theatre industry. </p>',
    course_duration_per_week = 156,
    total_course_duration = '3 year(s) full-time only (no part time option)',
    offshore_tuition_fee = 45600,
    onshore_tuition_fee = NULL,
