-- Course: Bachelor of Nursing (057076J)
UPDATE courses SET
    course_description = '<p>The Bachelor of Nursing is a clinically focused degree, offering valuable industry insights and the best in nursing practice. Learn from experienced academic and clinical staff in our simulated hospital and health service environments where you can consolidate your learning and build confidence in your practice.</p><p>Complete 880 placement hours, providing you opportunities to learn and experience the diversity of nursing practice and healthcare. Explore some of the latest technologies in healthcare including the use of 360 video and augmented reality.</p><p>This degree prepares you to meet the <em>Registered Nurse standards for practice</em> <em>(2016) </em>required for a registration as nurse with the Nursing and Midwifery Board of Australia.</p><p>You will also have opportunities to further your studies and specialise in an area that meets your career aspirations.</p><p>You can also choose to study this program at our regional campuses in <a href="https://adelaideuni.edu.au/why-adelaide/campuses/mount-gambier-campus/" rel="noopener noreferrer" target="_blank">Mount Gambier</a> and <a href="https://adelaideuni.edu.au/why-adelaide/campuses/whyalla-campus/" rel="noopener noreferrer" target="_blank">Whyalla</a>.</p>',
    course_duration_per_week = 156,
    total_course_duration = '3 year(s) full-time',
    offshore_tuition_fee = 46700,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE)</li><li>Completion of an award from a registered training organisation (RTO) at Certificate IV (AQF level 4) or higher</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program</li><li>Australia ATAR 70</li><li>Bangladesh Higher Secondary Certificate (HSC) 4.80</li><li>Canada Ontario Secondary School Diploma (OSSD) 65%</li><li>China Gaokao 60%</li><li>Denmark Studentereksamen (stx: Upper Secondary School Diploma) 4 (Fair)</li><li>France French Baccalaureate 11.0</li><li>Global International Baccalaureate 25</li><li>Hong Kong Diploma of Secondary Education (HKDSE) 16</li><li>India CBSE and CISCE 65</li><li>India State Board Examinations 80</li><li>Indonesia SMA III 75%</li><li>Kenya Certificate of Secondary Education (KCSE) B+</li><li>Malaysia Matrikulasi 2.67</li><li>Malaysia Sijil Tinggi Persekolahan Malaysia (STPM) 2.67</li><li>Malaysia United Entrance Certificate (UEC) 23</li><li>Nepal National Examinations Board (NEB) 2.81</li><li>Norway Upper Secondary School Certificate (Vitnemal fra den Videregaende Skole) / Vitnemal For Videregaende Opplaering 3.2</li><li>Philippines High School Diploma (Grade 12) (Academic Track) K12 86%</li><li>Singapore Singapore GCE Advanced Levels 7</li><li>South Korea College Scholastic Ability Test (CSAT) 300</li><li>Sri Lanka GCE A Levels 8</li><li>Sweden Upper Secondary School Leaving Certificate 13.0</li><li>Taiwan GSAT % 60%</li><li>Thailand Matayom 6 3.20</li><li>UK / Global GCE Advanced Levels 7</li><li>USA / Global Advanced Placement (AP) 7</li><li>USA / Global America College Test (ACT) 21</li><li>USA / Global Scholastic Assessment Test (SAT) 1100</li><li>Vietnam Bằng Tốt Nghiệp Trung Học Phổ Thông (Vietnamese Year 12) 7.8</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last year prior to admission</li><li>IELTS Overall 7, Reading 7, Listening 7, Speaking 7, Writing 7</li><li>Equivalent English qualifications accepted by Adelaide University (link provided)</li><li>Where previous study/work experience was conducted in English, application must be accompanied by certified documentation from educational institution/employer certifying language of instruction/employment was English</li><li>Applicants must meet NMBA English Language Skills standard</li><li>Applicants complete a declaration stating how they demonstrate English language proficiency, which in some cases may require provision of English language test results</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Prior to admission, applicants must meet professional registration requirements set by the Nursing and Midwifery Board of Australia (NMBA)</li><li>Upon entry to the program, all students must confirm they meet the Fitness to Practice in Clinical Placements requirements</li><li>Possession of qualifications in addition to academic entry requirements does not guarantee a place; applications considered individually and selection is competitive</li><li>Adelaide University recognises prior learning; credit may be granted for formal, informal, and non-formal learning</li><li>Online Credit Assessor available to see what credit could be obtained</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/bachelor-of-nursing/',
    updated_at = NOW()
WHERE cricos_course_code = '057076J';

-- Course: Bachelor of Agricultural Sciences (069204G)
UPDATE courses SET
    course_description = '<p>Adelaide University’s Bachelor of Agricultural Sciences provides broad training in science and agriculture. Agriculture is more than just production. Discover social and environmental settings of farms and the lifecycle of producing products for consumption with our hands-on program.</p><p>You’ll develop basic skills in chemistry, biology and statistics and build knowledge in soils and agriculture. You’ll also learn key concepts in crop and pasture science, horticulture, livestock science, soil science and agribusiness.</p><p>Our comprehensive program includes field trips and excursions throughout your three-year degree. Exposure to industry will come from study tours across South-East South Australia and Queensland. Gain practical skills through industry internships, preparing you for life after graduation.</p><p>Agricultural Science graduates are highly sought after in Australia. You might find yourself consulting in the livestock and cropping industries – or working in biosecurity, agribusiness, research or natural resource management.</p>',
    course_duration_per_week = 156,
    total_course_duration = '3 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
