-- Course: Graduate Diploma in Forensic Odontology (002798G)
UPDATE courses SET
    course_description = '<p>Our Graduate Diploma in Forensic Odontology has a strong practical focus. This specialised program is designed for licensed dental professionals seeking to expand their expertise into the field of forensic odontology. </p><p>You’ll discover professional handling, examination, interpretation and presentation of dental and oral evidence. Get trained in court procedures and giving expert testimony. You’ll be prepared to work competently in both civil and criminal jurisdictions. </p><p>Learn through video and computer imaging techniques. Take advantage of our hands-on approach to deal independently with routine forensic odontological casework. Explore how to prepare evidence for legal proceedings. Contribute to disaster victim identification efforts. </p><p>Gain an understanding of forensic medicine and pathology principles. Develop the knowledge and skills to create a rewarding career in this subspeciality of dentistry through theoretical and practical study. </p><p>Uncover the intersection of dental science and forensic investigation with Adelaide University. Open new career opportunities in law enforcement, disaster response and legal consultation. </p>',
    course_duration_per_week = 52,
    total_course_duration = '1 year(s) full-time',
    offshore_tuition_fee = 77000,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed Bachelor of Dental Surgery (or higher) from a recognised higher education institution</li><li>At least two years'' experience in general dental practice</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>Admission will be competitive with ranks based on the entry criteria where there are more eligible applicants than available places</li><li>Recognition of prior learning: Credit may be granted for formal, informal, and non-formal learning</li><li>Use online Credit Assessor to see what credit you could get</li></ul></td></tr><tr><td><strong>Interview</strong></td><td><ul><li>An updated CV that provides comprehensive academic and employment history as well as current clinical position held</li><li>2 referees on official letterhead</li><li>1 page statement of interests and aptitudes</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications link available for comprehensive list of accepted tests</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/graduate-diploma-in-forensic-odontology/',
    updated_at = NOW()
