-- Course: Graduate Diploma in Addiction and Mental Health (107540E)
UPDATE courses SET
    course_description = '<p>Unravel the complex relationship between addiction and mental illness and explore evidence-based approaches to care in our Graduate Diploma in Addiction and Mental Health. </p><p>Taught by world-class academics and researchers who are experienced in the field, you’ll complete courses that explore the scientific bases of addiction, mental health and related comorbidities. Learn best practice, culturally safe approaches to care for a diverse range of client populations and contexts – from Aboriginal and Torres Strait Islander cultures, migrant cultures, adolescence, pregnancy and childbirth, and defence forces to other specialised areas. </p><p>Develop broad knowledge of the biological basis of addiction and mental illness, including individual and community-based risk and protective factors. Examine of the sociological, cultural and political factors that influence addiction and mental health care professional practice and policy. Gain in-depth knowledge of the psychological and pharmacological approaches to treatment, alongside public health-driven approaches to prevention and harm reduction. </p><p>Emerge with the specialised skillset to lead best practice approaches in your professional field – whether that’s undertaking further research, developing public health policy, designing prevention or harm reduction initiatives or approaches to healthcare. </p>',
    course_duration_per_week = 52,
    total_course_duration = '1 year(s) full-time',
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) degree or equivalent from a recognised higher education institution; AND</li><li>Relevant work experience</li></ul></td></tr><tr><td><strong>Other</strong></td><td>All applicants must upload the following documents as part of the SATAC application: Current Curriculum Vitae (CV)</td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/graduate-diploma-in-addiction-and-mental-health/',
    updated_at = NOW()
WHERE cricos_course_code = '107540E';

-- Course: Master of Psychology (Organisational and Human Factors) (042771J)
UPDATE courses SET
    course_description = '<p>Inspire change and improve people''s experiences in the workplace with our Master of Psychology (Organisational and Human Factors). </p><p>As one of only five organisational psychology degrees in Australia, it prepares you for a fulfilling career as a registered psychologist, specialising in work and organisations. </p><p>Through a blend of coursework, 1000 hours of industry placements and research, you’ll explore the dynamics of teamwork and leadership. Acquire evidence-based strategies to promote adaptability and resilience in the workplace. Discover how to motivate employees and gain insights into emerging trends like remote work, diversity and organisational change. </p><p>You’ll develop the skills to contribute across the entire work lifecycle, from recruitment and career development to performance management and leadership. Build your expertise in undertaking psychological assessments and professional practice. </p><p>Graduate ready to make a significant impact – not only within organisations, but on broader societal issues like unemployment, workforce development and economic growth. </p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>A completed four-year psychology honours degree with at least an upper second class or equivalent overall mark, or an equivalent degree that is accredited by the Australian Psychology Accreditation Council</td></tr><tr><td><strong>Interview</strong></td><td>Attend an interview, if invited</td></tr><tr><td><strong>Other</strong></td><td><ul><li>Undertake the Casper Situational Judgement Test (CSJT)</li><li>Provide two referee reports via the HODSPA – VTAC reference portal system</li><li>Admission will be competitive with ranks based on the entry criteria where there are more eligible applicants than available places</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>IELTS Overall 7</li><li>IELTS Reading 7</li><li>IELTS Listening 7</li><li>IELTS Speaking 7</li><li>IELTS Writing 7</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-psychology-organisational-and-human-factors/',
    updated_at = NOW()
WHERE cricos_course_code = '042771J';

